function current_user(PDO $pdo): ?array {return $GLOBALS['actor'] ?? null;}
function require_admin(PDO $pdo): array {$u=current_user($pdo);if(!$u||!in_array($u['role'],['admin','manager'],true))response(['message'=>'Forbidden'],403);return $u;}
require __DIR__.'/../api/marketplace.php';
function ensure(bool $ok,string $message): void {if(!$ok)throw new RuntimeException($message);}
function endpoint(PDO $pdo,string $path,string $method='GET',array $payload=[],int $expected=200): array {$GLOBALS['payload']=$payload;try{market_route($pdo,$path,$method);throw new RuntimeException('Missing response');}catch(CorrectionResult $r){if($pdo->inTransaction())$pdo->rollBack();ensure($r->status===$expected,"$method $path expected $expected got {$r->status}: ".json_encode($r->data));return $r->data;}}
